      "rank": 2,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten"
      ],
      "assessment": {
        "nobel_worthiness": "The gauge/gravity correspondence transformed theoretical physics by connecting quantum field theory and gravity and supplying powerful tools across several fields.",
        "attribution": "Maldacena's proposal was seminal; Witten gave the correspondence broad mathematical and physical development. Polyakov's earlier work helped establish the conceptual lineage.",
        "maturity": "The correspondence is extensively developed and tested through internal consistency and applications, though it is not an experimentally verified description of our universe.",
        "uncertainties": [
          "Its empirical connection to nature remains indirect.",
          "The breadth of foundational contributions makes the boundary of prize-worthy attribution debatable."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation and the account of primordial fluctuations address foundational questions about the early universe and connect theoretical ideas to precision cosmology.",
        "attribution": "Guth introduced the inflationary scenario, Linde substantially developed it, and Mukhanov made a key contribution to the theory of primordial perturbations.",
        "maturity": "The broad framework is consistent with observations, and the origin of cosmic structure is strongly supported; the specific inflationary model and quantum origin are not uniquely established.",
        "uncertainties": [
          "There is no decisive identification of a particular inflation model.",
          "The discovery's empirical claims and the named theorists' distinct contributions need careful separation."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Alexander A. Belavin",
        "Alexander B. Zamolodchikov",
        "Alexander M. Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Two-dimensional conformal field theory and exact critical phenomena supplied deep, widely used methods for understanding critical systems and quantum field theory.",
        "attribution": "The cited work is closely associated with Belavin, Polyakov, and Zamolodchikov, whose contributions established a powerful framework rather than one isolated result.",
        "maturity": "The framework has been confirmed and applied across decades of theoretical and experimental work on critical systems.",
        "uncertainties": [
          "The division between the foundational result and the broader development of conformal methods is not sharp."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made controlled quantum many-body simulation experimentally accessible and opened a sustained research program.",
        "attribution": "Zoller helped establish the theoretical vision; Bloch and Greiner led landmark experimental demonstrations. The contribution is shared across theory and experiment.",
        "maturity": "The platform is well established and produces increasingly capable simulations, though its reach as a predictive tool for difficult materials remains under development.",
        "uncertainties": [
          "The most consequential scientific insights enabled by the platform may still lie ahead.",
          "Important contributions from other groups are not represented in the credited names."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John",
        "John D. Joannopoulos"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals and band gaps for light introduced a major design principle in optics, with influence on photonics and the control of light-matter interactions.",
        "attribution": "Yablonovitch and John independently established the central photonic-band-gap idea; Joannopoulos made major contributions to its theory and development.",
        "maturity": "The concept is established and has driven decades of research and applications, though proposed control of spontaneous emission has not been realized in every anticipated form.",
        "uncertainties": [
          "The boundary between the independent foundational proposals and later developments affects how credit should be divided."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Mikhail D. Lukin",
        "Antoine Browaeys",
        "Mark Saffman"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade enabled strongly interacting, individually controlled neutral atoms and programmable arrays, creating a powerful platform for quantum simulation and information processing.",
        "attribution": "Lukin helped establish the blockade-based approach; Browaeys and Saffman made major experimental and platform-building contributions. Credit spans foundational proposals and independent experimental programs.",
        "maturity": "The arrays and their control are now highly capable, but the most important applications and lasting scientific results are still emerging.",
        "uncertainties": [
          "The eventual scientific impact of programmable arrays is not yet clear.",
          "The credited set may omit other central contributors to the field's experimental foundations."
        ]
      }
    },
    {
      "rank": 8,
