      "proposed_laureates": [
        "Charles H. Bennett",
        "Gilles Brassard",
        "Artur Ekert"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum cryptography established a fundamental connection between quantum measurement and secure communication, with influence beyond its practical protocols.",
        "attribution": "Bennett and Brassard introduced the landmark BB84 protocol; Ekert independently developed an entanglement-based approach that made the link to nonlocal correlations explicit.",
        "maturity": "The principles are established and quantum key distribution has been demonstrated in increasingly capable systems, though broad deployment remains limited.",
        "uncertainties": [
          "The extent to which practical communication systems will depend on these protocols remains unsettled.",
          "The prize case should distinguish foundational physics from later engineering."
        ]
      }
    }
  ]
